-- Insert Quiz Questions for Lesson: What Is an Opportunity?

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 5 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 5 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'what-is-opportunity' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson what-is-opportunity not found in module 5';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is an Opportunity?', 
    '["Just a name in your contacts","A lead, contact, or business that could become a client","A completed sale","A marketing campaign"]'::jsonb,
    'A lead, contact, or business that could become a client',
    'An Opportunity is a lead, contact, or business that could become a client. It represents possible business, not just a contact name.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When should you create an Opportunity?', 
    '["Only after they have paid","When they show interest by filling out a form, booking a call, asking for pricing, or inquiring about services","Only for existing customers","Never, Opportunities are not useful"]'::jsonb,
    'When they show interest by filling out a form, booking a call, asking for pricing, or inquiring about services',
    'Create an Opportunity when someone shows interest in becoming a client - through form submissions, call bookings, pricing inquiries, or service questions.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What information does an Opportunity help you track?', 
    '["Only the person''s name","Who the lead is, what they want, where they are in the process, the value, what happened, and what''s next","Only their email address","Only the final sale amount"]'::jsonb,
    'Who the lead is, what they want, where they are in the process, the value, what happened, and what''s next',
    'An Opportunity tracks comprehensive information: who the lead is, what they are interested in, their stage in the sales process, possible value, recent activity, and next steps.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
